  with open(tmp,"xb") as f:f.write(changed);f.flush();os.fsync(f.fileno())
  os.chown(tmp,uid,gid);os.chmod(tmp,mode)
  if p.read_bytes()!=b:raise RuntimeError("concurrent_source_change")
  os.replace(tmp,p);modified.append(p)
 if run(["systemd-analyze","verify",str(unit)])!=0:raise RuntimeError("unit_syntax_postcheck")
 if run(["systemctl","daemon-reload"])!=0:raise RuntimeError("daemon_reload_failed")
 reload_done=True
 for p in targets:
