 if svc()!=before:raise RuntimeError("service_status_changed")
 out.update(status="CANONICAL_CODE_AND_UNIT_VERIFIED",changed=True,source_files_updated=[p.name for p in targets],unit_verified=True,systemd_daemon_reloaded=True,services_unchanged=True,backup_within_project=True,vpn_not_restarted=True)
